local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["ea02c0dd1c9132d7"] = { "L'⟦Horde=Orda⟧ ha preso la East Frostwolf Tower!", "." },
  ["ea0348978aa13a60"] = { "Stai dicendo sciocchezze, mago.", "." },
  ["ea08380a2c00979d"] = { "Ho bisogno di un teletrasporto per Naxxramas.", "." },
  ["ea0a750229cd214d"] = { "%s si asciuga la fronte.", "." },
  ["ea1282cc06bd17e4"] = { "Immagino che tu non sia qui per parlare della mia adorata Kali. E va bene. Pozioni, allora. Nessuno ti ha mai detto che pensi sempre e solo a una cosa?", "." },
  ["ea18e8dbac79b36e"] = { "Ti consiglio vivamente di andare da Sayge a farti predire il futuro. Lo so, lo so... è uno gnoll. Ma è uno gnoll davvero speciale, con il potere di divinare il tuo futuro!\n\nE stiamo continuamente ampliando la fiera con ogni sorta di nuove attrazioni!", "." },
  ["ea1c60052cc54717"] = { "Il tuo mondo subirà una fine spietata. L'Incubo viene a prenderti!", "." },
  ["ea1ceaa381fb2be4"] = { "Questa raccolta di pergamene contiene varie informazioni logistiche e strategiche, oltre a corrispondenza in codice.", "." },
  ["ea1f79a44f1fdabb"] = { "⟦First Aid=Primo Soccorso⟧", "." },
  ["ea23a72f908da431"] = { "Sì? Hai qualcosa da riferire?", "." },
  ["ea28f8d0ddc27675"] = { "Quali merci ho il diritto di acquistare da usare nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧?", "." },
  ["ea2dd2e8cbdcd1e4"] = { "A meno che tu non sia qui per affari che riguardano la V.L.O., temo di non avere molto tempo per le chiacchiere. Se però vuoi darti da fare e aiutare in città, ti metterò volentieri al lavoro.\r\n\nOh, cosa significa V.L.O.? Village Live Operations, naturalmente. Nemmeno le città di frontiera come questa si gestiscono da sole. Tra incidenti gravi, blackout imprevisti dell'energia eolica e infestazioni di insetti, mandare avanti questo posto non è uno scherzo.", "." },
  ["ea30e585795a0029"] = { "CHI UCCIDE GOR'TESH!?!? CHI FA QUESTO?!", "." },
  ["ea370192885b94a5"] = { "Rin'ji ora vede la strada, {name}. Rin'ji conosce la via di casa.", "." },
  ["ea38f1bcb41cb9ed"] = { "Mm... non credo che questa luce rossa lampeggiante sia una buona cosa...", "." },
  ["ea3a3b49d1ed36a1"] = { "Non avvicinarti troppo, {name}. Rischio di perdere la presa e di spaccarti il cranio con la testa del martello.", "." },
  ["ea3cd6b3fdd383d6"] = { "Negli ultimi mesi abbiamo ampliato rapidamente la nostra attività, ma stiamo ancora sviluppando i mezzi per garantire comunicazioni rapide con i clienti di ogni angolo del mondo. Per questo dobbiamo tenere gli occhi aperti per trovare occasioni che tengano occupate le mani dei nostri artigiani. Contiamo su corrieri e altre anime coraggiose che ci portino direttamente gli ordini di lavorazione.\r\n\nPuoi immaginare che un modello del genere comporti delle difficoltà. Nel frattempo incoraggiamo vivamente i nostri artigiani a soddisfare questi ordini e a consegnare la merce di persona ai clienti, ovunque si trovino in quel momento. Non temere, amico: sarai ricompensato equamente per il disturbo e ti guadagnerai il nostro rispetto!", "." },
  ["ea3f7a39993ed4fd"] = { "Riporta il Crest of Lordaeron a lady Dena Kennedy a ⟦Stormwind City=Roccavento⟧.", "." },
  ["ea3f9f0c7c7da976"] = { "Ah, sì. Ho sentito tutto su quelle nuove cose flargiate. Hanno tolto la corazza dall'involucro per ridurre il peso. Bargh! Sciocchezze!", "." },
  ["ea3fec9d24aa19c4"] = { "Contro un incantatore di qualsiasi tipo, questa bestia feroce sarà la tua migliore amica. Ora diamo un'occhiata a qualcosa di un po' diverso. La prossima creatura ti aiuterà nei viaggi e renderà molto più facili i tuoi spostamenti futuri. Diamo un'occhiata a un destriero vile.", "." },
  ["ea401e53772b8011"] = { "Farò una fortuna con queste corna, {name}. Grazie!", "." },
  ["ea422d872d6f5f01"] = { "Ti istruirò quando sarà il momento giusto... e quel momento non è adesso. Prima hai ancora molto da imparare!", "." },
  ["ea43ee9b4ac3c2e6"] = { "Cammina con cautela, mortale. Calpesti un luogo dove esseri più potenti di te hanno incontrato il loro destino.", "." },
  ["ea4dd879df0a23f0"] = { "Cerca Turak Runetotem nella Hall of Elders, sull'⟦Elder Rise=Altura degli Anziani⟧.", "." },
  ["ea5dcf17dd3eacbe"] = { "Temo il peggio, vecchio amico. Nel Sogno combattiamo un nuovo nemico, nato da un male antico. La nobile progenie di Ysera è caduta vittima degli antichi sussurri. Sembra che l'Incubo abbia sfondato il reame e cerchi un nuovo ospite su Azeroth.", "." },
  ["ea64223e28dea867"] = { "Quell'istruttore si trova in una casa vicino al molo dell'High Order, sul margine sud-orientale della città.", "." },
  ["ea65dafd236b4eca"] = { "Questo cultista è in uno stato di trance profonda...", "." },
  ["ea6809cd554445a1"] = { "State all'erta! I mezzorsi Blackwood sono numerosi in questa zona...", "." },
  ["ea8b6f1f7d62b8e3"] = { "Ti do il benvenuto nella mia bottega, è bello vedere qui a ⟦Stormwind=Roccavento⟧ qualcun altro che pratica la Sartoria. Sei qui per una lezione, forse?", "." },
  ["ea8c62887c49ced3"] = { "Restituisci l'amuleto! Ridammi ciò che è stato rubato!!", "." },
  ["ea8e8790634a0f7c"] = { "Buongiorno, <ragazzo/ragazza>! Forse potresti aiutarmi con alcune faccende da sbrigare.", "." },
  ["ea931cf0adcd88f8"] = { "Eh?!? Oh. Non sembri un ladro dei Defias... né qualcuno dei Guardiani della Notte. Abbi pietà di un'anima sventurata, eh?", "." },
  ["eaa3649e6f3bd767"] = { "%s tracanna la sua bevanda.", "." },
  ["eaa53ed3bb3075c6"] = { "Il capitano Galvangar è il fidato braccio destro di Drek'Thar. Guida le forze dell'⟦Horde=Orda⟧ dal ⟦Iceblood Garrison=Presidio di Brinarossa⟧, nella parte meridionale del ⟦Field of Strife=Pian della Discordia⟧.\n\nIl capitano Galvangar non è ancora entrato in battaglia.", "." },
  ["eab2423718ab026e"] = { "Mmm, credo che dovrai salire a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare quello. Prendi la strada verso nord che esce dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Ti porterà ai piedi di ⟦Thunder Bluff=Picco del Tuono⟧. Prendi l'ascensore fino in cima e potrai chiedere ulteriore aiuto a uno qualsiasi dei Bluffwatcher.", "." },
  ["eab2b7815469a591"] = { "Ora Hendel è in nostra custodia, {name}, grazie a te.\n\nAnche se l'interrogatorio procede a rilento, ti assicuro che ci dirà tutto ciò che sa.\n\nPer ora, ti prego, abbi pazienza. Ti contatterò immediatamente se avremo bisogno del tuo aiuto.\n\nNel frattempo, ti prego, goditi Theramore: ti invito a restare tra le mura della nostra città per tutto il tempo che vuoi, come <amico/amica> dell'⟦Alliance=Alleanza⟧.", "." },
  ["eab70452ff3c5278"] = { "%s, con ferite troppo gravi, rinuncia all'inseguimento.", "." },
  ["eab77e34f28a3df6"] = { "{name}, svelare il segreto di questi collari va oltre le mie capacità...", "." },
  ["eab93f1f6dd92663"] = { "Che il fuoco arda nel tuo cuore, {name}.\n\nGli elementi ti attendono.", "." },
  ["eaba8d566bfd88cb"] = { "Purificazione attraverso il dolore!", "." },
  ["eac6575607d8e8ea"] = { "Grazie, Ragged John. La tua storia è stata molto edificante e istruttiva.", "." },
  ["eac9370c77062388"] = { "Ah! Ben ti sta, lurido trogg!!", "." },
  ["ead0334f22c5c563"] = { "Non è proprio il risultato che mi aspettavo. Potresti recuperare le mie catene?", "." },
  ["ead471e3bcac2f5b"] = { "Non siamo gente maleducata, <straniero/straniera>, è solo che tutti vanno di fretta per assicurarsi che sia tutto perfetto per l'arrivo di Uther. Non capita spesso che l'Araldo della Luce venga in città.", "." },
  ["ead4a910cfc69c9e"] = { "Ho sentito che tutti i coboldi che stavano laggiù sono morti.", "." },
  ["eadc8682795d6390"] = { "Certo, certo. Abbiamo un istruttore di Estrazione proprio qui in città. Cerca Krunn nell'angolo nord-occidentale, accanto alla locanda.", "." },
  ["eadd51340effa30c"] = { "Non merito tanto, signore.", "." },
  ["eadde088653f7dc7"] = { "Udite, abitanti di Tanaris! Sia noto a tutti che {name} è un membro osannato del Mithril Order. Un fabbro d'onore, dedizione e pazienza infinita. Tre urrà per {name}!", "." },
  ["eae5b0529361e224"] = { "Mostramele!", "." },
  ["eaf5d7b612a775cb"] = { "Sfrontatezza. Al maestro ⟦Ravenholdt=Corvolesto⟧ la sfrontatezza non piace.", "." },
  ["eaff9284e1e3663c"] = { "Maledetti coboldi. Non riesco a combinare niente con loro che corrono avanti e indietro e mi stanno tra i piedi. Be', non ho niente di meglio da fare. Vuoi imparare qualche tecnica di estrazione? O forse ti servono solo degli attrezzi nuovi?", "." },
})
